"""Money arithmetic for invoices."""
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")


def _dec(amount):
    if isinstance(amount, Decimal):
        return amount
    return Decimal(str(amount))


def line_total(qty, unit_price):
    return (_dec(qty) * _dec(unit_price)).quantize(CENTS, rounding=ROUND_HALF_UP)


def total(lines):
    return sum(
        (line_total(l["qty"], l["unit_price"]) for l in lines), Decimal("0.00")
    )

